import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"通用","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/general.md","filePath":"zh-CN/user-guide/settings/general.md","lastUpdated":1784885652000}'),s={name:"zh-CN/user-guide/settings/general.md"};function n(i,t,l,g,p,h){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h1><p>五个 Tab:<strong>系统</strong>、<strong>快速搜索窗口</strong>、<strong>完整搜索窗口</strong>、<strong>预览窗口</strong>、<strong>快速导航</strong>。</p><h2 id="系统" tabindex="-1">系统 <a class="header-anchor" href="#系统" aria-label="Permalink to &quot;系统&quot;">​</a></h2><ul><li><strong>开机自动启动 SwiftList</strong> —— 复选框，登录时自动启动。</li><li><strong>启动时自动检查更新</strong> —— 复选框。</li><li><strong>自动静默更新</strong> —— 复选框，仅在上面的选项开启时可用；检测到新版本时在后台静默下载安装，不弹 窗提示。</li><li><strong>启用硬件加速</strong> —— 复选框，默认开启。关闭后会让快速搜索窗口改用软件渲染而不是 Direct3D——用 来解决 NVIDIA Advanced Optimus 因为 SwiftList 在运行而拒绝切换显卡的问题(只影响快速窗口，不影 响整个 App)。需要重启 SwiftList 才能生效。</li><li><strong>隐藏托盘图标</strong> —— 复选框，默认关闭。立即生效，不需要重启。不管这个设置开不开， <a href="./../hotkeys.html#搜索框图标">快速窗口自带的图标</a>始终能打开和托盘图标右键一样的菜单，所以隐藏托盘图 标不会让你找不到设置或退出的入口。</li><li><strong>日志等级</strong> —— 下拉框:错误 / 警告 / 信息(默认)/ 调试。控制 App、Service、Hook 三处日志(见 <a href="./service-status.html">运行状态</a>)的详细程度。</li><li><strong>界面语言</strong> —— 下拉框，内容来自所有已安装的语言包提供者(内置语言加上任何插件新增的语言)。</li></ul><p>主题选择已经移到独立的<a href="./appearance.html">外观</a>分区——主题选择器和&quot;跟随系统浅色/深色设置&quot;选项都在 那一页。</p><h2 id="快速搜索窗口" tabindex="-1">快速搜索窗口 <a class="header-anchor" href="#快速搜索窗口" aria-label="Permalink to &quot;快速搜索窗口&quot;">​</a></h2><p>涵盖快速搜索栏的外观布局，以及它搜索结果的类型优先级。</p><p><strong>搜索栏布局</strong> —— 自定义快速搜索栏的大小以及屏幕显示位置:</p><ul><li><strong>搜索栏宽度(像素)</strong> —— 范围 300–1200px，默认 570px。</li><li><strong>搜索栏高度(像素)</strong> —— 范围 45–120px，默认 60px。这一个数值同时驱动结果行的图标大小、名称/ 路径字体大小和行高(<code>高度 / 60</code>)，所以搜索栏调高，整个结果列表也会跟着放大，图标和文字始终保持 同样的比例。</li><li><strong>搜索框内显示时钟</strong> —— 复选框，默认关闭。开启后，当搜索框为空时会用当前日期、星期几和时间替 换掉原本的&quot;输入以搜索...&quot;提示文字。一开始输入内容，时钟就会和提示文字一样消失。只影响快速窗 口——内联窗口不管这个设置开没开，都保持它自己原本的提示文字。</li><li><strong>再次按下快捷键时打开完整窗口</strong> —— 复选框，默认关闭。正常情况下，快速窗口已经打开时再按一次 呼出热键只会隐藏它；开启这个选项后，第二次按下会改为切换到完整窗口(带上已经输入的查询内容)， 而不是直接关闭。</li><li><strong>重置布局设置</strong> 按钮 —— 把以上四项都恢复为默认值。</li></ul><p>在<a href="./../hotkeys.html#搜索框图标">快速窗口的图标</a>上右键，可以单独重置它的屏幕位置(不影响大小)，效果和 首次启动时的居中方式一样。</p><p><strong>结果类型优先级</strong> —— 跟下面<a href="#快速导航">快速导航</a>同一套上移/下移(也可以拖动)排序列表：把某个结果类型(应用程 序、系统设置、文件过滤器、任何第三方插件自己提供的可搜索项，或内置的&quot;文件&quot;条目)上移，就能让它在 快速窗口的结果里始终排在下面的类型前面，不管实际上谁的文本匹配得更好。历史记录和收藏夹始终排最 前，不受这个列表影响。</p><p>每个类型还可以单独配一个单字符<strong>触发符</strong>(可选，每行一个输入框)：在快速窗口里把这个字符打在最前 面，就只会显示这个类型的结果，其他全部隐藏——具体例子见<a href="./../search-syntax.html#结果类型触发符">搜索语法</a>。 只打触发符、后面还没打内容时，会显示&quot;继续输入以只搜索……&quot;这样的提示，而不是&quot;无搜索结果&quot;。挑一个 平时正常搜索绝对不会以它开头的字符，因为一旦分配给某个类型，这个字符就等于被占用了——建议用标点 符号(比如 <code>;</code>)而不是纯空格，因为只打一个空格、后面没有内容时会被当成搜索框为空处理，不会显示 这个提示。</p><h2 id="完整搜索窗口" tabindex="-1">完整搜索窗口 <a class="header-anchor" href="#完整搜索窗口" aria-label="Permalink to &quot;完整搜索窗口&quot;">​</a></h2><p>设置完整/主搜索窗口(从任务栏或开始菜单快捷方式打开的那个更大的窗口，区别于快速弹出搜索栏——见 <a href="./../getting-started.html#三种窗口">快速上手</a>)的默认大小:</p><ul><li><strong>窗口宽度(像素)</strong> —— 范围 640–2000px，默认 854px。</li><li><strong>窗口高度(像素)</strong> —— 范围 400–1400px，默认 480px。这两个下限分别对应窗口自身可拖拽调整的最 小尺寸，所以配置的值不会被窗口自己悄悄覆盖。</li><li><strong>重置搜索窗口设置</strong> 按钮。</li></ul><p>手动拖拽窗口边缘调整大小时会自动记住这个尺寸——下次打开窗口(或新开一个)时会沿用上次离开时的大 小，本页面上的数值也会同步更新。在窗口处于最大化状态时调整不会覆盖已记住的尺寸，只有在正常(非最 大化)状态下调整才会被记住。</p><p><strong>结果表格列顺序</strong> —— 跟设置里其它地方(见<a href="./favorites.html">收藏夹</a>)同一套排序列表：把结果表格里的 某一列(名称、路径、修改时间，或任何插件新增的列)左移或右移。只影响表格视图的结果列表——精简列 表视图里没有列可以排序。</p><p><strong>侧边栏筛选顺序</strong> —— 同样的机制，调整侧边栏筛选分组(类型、修改时间，以及任何插件新增的分组) 的先后顺序。</p><p>点击结果表格的列标题来排序，这个排序只在 SwiftList 运行期间有效——退出应用(不只是关闭窗口)后 下次打开会恢复默认排序，跟上面永久保存的列/侧边栏顺序不一样。</p><h2 id="预览窗口" tabindex="-1">预览窗口 <a class="header-anchor" href="#预览窗口" aria-label="Permalink to &quot;预览窗口&quot;">​</a></h2><ul><li><strong>预览窗口宽度(像素)</strong> —— 范围 250–900px。</li><li><strong>预览窗口高度(像素)</strong> —— 范围 250–1200px，默认值不会在常见显示器上显得过高。</li><li><strong>重置预览窗口设置</strong> 按钮。</li></ul><p>预览窗口的尺寸是固定的，不受当前结果数量影响——它不是一个随内容变化的自适应大小。预览面板具体如 何定位，见<a href="./../actions-and-preview.html">动作菜单与预览</a>。</p><h2 id="快速导航" tabindex="-1">快速导航 <a class="header-anchor" href="#快速导航" aria-label="Permalink to &quot;快速导航&quot;">​</a></h2><p>设置<a href="./../hotkeys.html#快速导航鼠标">快速导航</a>菜单根层级各个分组的先后顺序——每个贡献条目的 provider 一 个分组(比如收藏夹/历史记录/配置好的快捷文件夹、Total Commander 的 Directory Hotlist、某个插件自 己的快速导航条目)，各自带一个标题。</p><p><strong>提供者顺序</strong> —— 跟设置里其它地方(见<a href="./favorites.html">收藏夹</a>)同一套上移/下移(也可以拖动)排序列表：把某个 provider 上移或下移，就能改变它的分组相对其它分组出现的位置。这里只列出插件组件当前处于启用状态 的 provider——在<a href="./plugins.html">插件</a>里整体禁用的组件从一开始就不会成为菜单候选项，也就没有顺序可调。</p>',25)])])}const c=r(s,[["render",n]]);export{u as __pageData,c as default};
